<?php
namespace App\Services;
use App\Models\Employee; use App\Models\EmployeeContract; use App\Models\EmployeeLeaveBalance; use App\Models\LeaveAccrualPolicy; use Illuminate\Support\Collection; use Illuminate\Support\Facades\DB;
class LeaveAccrualService {
 public function preview(int $year, ?int $month=null): Collection { return Employee::where('is_active',true)->get()->flatMap(function($e)use($year,$month){$contract=EmployeeContract::where('employee_id',$e->id)->where('is_active',true)->latest('start_date')->first(); return LeaveAccrualPolicy::with('leaveType')->where('is_active',true)->whereDate('effective_from','<=',now())->get()->filter(fn($p)=>!$p->contract_type||$p->contract_type===$contract?->contract_type)->map(function($p)use($e,$year,$month){$bal=EmployeeLeaveBalance::firstOrNew(['employee_id'=>$e->id,'leave_type_id'=>$p->leave_type_id,'year'=>$year]);$amount=(float)$p->accrual_amount; if($p->accrual_frequency==='annual'&&$month!==1&&$month!==null)$amount=0; $cap=$p->annual_cap!==null?(float)$p->annual_cap:null; if($cap!==null)$amount=max(0,min($amount,$cap-(float)$bal->accrued)); return ['employee'=>$e,'policy'=>$p,'balance'=>$bal,'accrual'=>$amount];});}); }
 public function apply(int $year, ?int $month, int $userId, string $note): array { $rows=$this->preview($year,$month); return DB::transaction(function()use($rows,$year,$month,$userId,$note){$total=0;foreach($rows as $r){if($r['accrual']<=0)continue;$b=EmployeeLeaveBalance::firstOrCreate(['employee_id'=>$r['employee']->id,'leave_type_id'=>$r['policy']->leave_type_id,'year'=>$year],['opening_balance'=>0,'accrued'=>0,'used'=>0,'adjusted'=>0]);$b->increment('accrued',$r['accrual']);$total+=$r['accrual'];}DB::table('leave_accrual_runs')->insert(['year'=>$year,'month'=>$month,'run_type'=>'accrual','status'=>'applied','summary'=>json_encode(['rows'=>$rows->count(),'days'=>$total]),'run_by'=>$userId,'applied_at'=>now(),'governance_note'=>$note,'created_at'=>now(),'updated_at'=>now()]);return ['rows'=>$rows->count(),'days'=>$total];}); }
 public function carryForward(int $fromYear, int $toYear, int $userId, string $note): array { $policies=LeaveAccrualPolicy::where('is_active',true)->where('carry_forward_enabled',true)->get()->keyBy('leave_type_id');$count=0;$days=0;DB::transaction(function()use($fromYear,$toYear,$userId,$note,$policies,&$count,&$days){EmployeeLeaveBalance::where('year',$fromYear)->get()->each(function($old)use($toYear,$policies,&$count,&$days){$p=$policies->get($old->leave_type_id);if(!$p)return;$carry=min(max(0,$old->available()),(float)$p->carry_forward_cap);if($carry<=0)return;$new=EmployeeLeaveBalance::firstOrCreate(['employee_id'=>$old->employee_id,'leave_type_id'=>$old->leave_type_id,'year'=>$toYear],['opening_balance'=>0,'accrued'=>0,'used'=>0,'adjusted'=>0]);$new->opening_balance=$carry;$new->save();$count++;$days+=$carry;});DB::table('leave_accrual_runs')->insert(['year'=>$toYear,'month'=>null,'run_type'=>'carry_forward','status'=>'applied','summary'=>json_encode(['balances'=>$count,'days'=>$days]),'run_by'=>$userId,'applied_at'=>now(),'governance_note'=>$note,'created_at'=>now(),'updated_at'=>now()]);});return ['balances'=>$count,'days'=>$days]; }
}
